/**
 * PublicationBadge — estado de una publicación en Mis publicaciones (Mi Garaje, mi-garaje-lab).
 * 7 estados: En revisión (violeta), Publicada (naranja), En negociación (cian), SubasChat (magenta),
 * Venta exitosa (verde), No concretada y Desierta (gris). Píldora de 19 px de alto y 80 de ancho mínimo.
 * PublicationPin: chincheta de una publicación fijada arriba de la lista; el nombre que la lleva va en negrita.
 * Incluye las animaciones de «Republicar» (atributo data-repub="spin|out|in" en la fila). Solo depende de React.
 */
import type { JSX } from "react";

export type PublicationStatus =
  | "revision" | "publicada" | "negociacion" | "subaschat"
  | "vendido" | "no-concretada" | "desierta";

export const PUBLICATION_LABEL: Record<PublicationStatus, string> = {
  revision: "En revisión",
  publicada: "Publicada",
  negociacion: "En negociación",
  subaschat: "SubasChat",
  vendido: "Venta exitosa",
  "no-concretada": "No concretada",
  desierta: "Desierta",
};

export const PUBLICATION_BADGE_CSS = String.raw`
.vpb { display: inline-flex; align-items: center; justify-content: center; gap: 4px; box-sizing: border-box; min-width: 80px; padding: 3px 8px 3px 6px;
  border: 1px solid transparent; border-radius: 9999px; color: #fff; white-space: nowrap; user-select: none;
  font-family: var(--vmc-font-display, 'Plus Jakarta Sans', -apple-system, sans-serif); font-size: 9px; font-weight: 700; letter-spacing: 0.07em; text-transform: uppercase;
  background-origin: padding-box, border-box; background-clip: padding-box, border-box;
  -webkit-backdrop-filter: blur(6px); backdrop-filter: blur(6px); }
.vpb svg { flex: none; }
/* En revisión: violeta */
.vpb--revision { background-image: linear-gradient(135deg, #8460E5 0%, #3B1782 100%), linear-gradient(135deg, #AE8EFF 0%, rgba(255,255,255,0.4) 38%, #5A35C2 68%, #AE8EFF 100%);
  box-shadow: rgba(34,0,92,0.5) 0 2px 10px, rgba(255,255,255,0.1) 0 1px 0 inset; }
/* Publicada: naranja */
.vpb--publicada { background-image: linear-gradient(135deg, var(--vmc-color-orange-gradient-light, #F4AC59) 0%, #ED8936 40%, #B25614 100%), linear-gradient(135deg, #FBC47D 0%, rgba(255,255,255,0.45) 40%, #D46E20 75%, #FBC47D 100%);
  box-shadow: rgba(237,137,54,0.45) 0 2px 10px, rgba(255,255,255,0.14) 0 1px 0 inset; }
/* En negociación: cian, el mismo de Negociable */
.vpb--negociacion { background-image: linear-gradient(135deg, #30E8EC 0%, #00CACE 45%, #008688 100%); box-shadow: rgba(0,134,136,0.4) 0 2px 10px, rgba(255,255,255,0.14) 0 1px 0 inset; }
/* SubasChat: magenta */
.vpb--subaschat { background-image: linear-gradient(135deg, #CC00FF 0%, #E6007E 55%, #FF0066 100%); box-shadow: rgba(204,0,255,0.35) 0 2px 10px, rgba(255,255,255,0.14) 0 1px 0 inset; }
/* Vendido: verde */
.vpb--vendido { background-image: linear-gradient(135deg, #4ADE80 0%, #16A34A 55%, #15803D 100%); box-shadow: rgba(22,163,74,0.35) 0 2px 10px, rgba(255,255,255,0.14) 0 1px 0 inset; }
/* No concretada (estuvo en SubasChat y no llegaron a nada) y Desierta (no recibió ofertas): gris */
.vpb--no-concretada, .vpb--desierta { color: #4A4855; background: #ECECEE; border-color: #DCDCE0; -webkit-backdrop-filter: none; backdrop-filter: none; }
/* Chincheta de una publicación fijada. El nombre va en negrita mientras siga fijada */
:has(> .vpb-pin) { font-weight: 700 !important; }
.vpb-pin { display: inline-block; width: 15px; height: 15px; margin-right: 4px; color: #3B1782; vertical-align: -2px; transform: rotate(40deg); }
/* Republicar: carga, se va el texto de antes, entra el nuevo y cambia el badge (data-repub en la fila) */
.vpb-spin svg { animation: vpb-spin .8s linear infinite; }
@keyframes vpb-spin { to { transform: rotate(360deg); } }
[data-repub="spin"] { background-image: linear-gradient(100deg, transparent 30%, rgba(132,96,229,.2) 50%, transparent 70%); background-size: 250% 100%; animation: vpb-sheen 1s ease-in-out infinite; }
@keyframes vpb-sheen { from { background-position: 120% 0; } to { background-position: -20% 0; } }
[data-repub="out"] .vpb-note, [data-repub="out"] .vpb { animation: vpb-out .33s ease-in forwards; }
[data-repub="out"] .vpb-pin { animation: vpb-fade .33s ease-in forwards; }
@keyframes vpb-out { to { opacity: 0; transform: translateY(-6px); filter: blur(3px); } }
@keyframes vpb-fade { to { opacity: 0; } }
[data-repub="in"] .vpb-note { animation: vpb-in .5s ease-out both; }
[data-repub="in"] .vpb { animation: vpb-pop .65s cubic-bezier(.2, 1.3, .4, 1) both; }
[data-repub="in"] .vpb-actions { animation: vpb-in .45s ease-out .25s both; }
@keyframes vpb-in { from { opacity: 0; transform: translateY(8px); filter: blur(3px); } }
@keyframes vpb-pop { 0% { opacity: 0; transform: scale(.6); } 60% { opacity: 1; transform: scale(1.12); } 100% { transform: scale(1); } }
@media (prefers-reduced-motion: reduce) { .vpb-spin svg, [data-repub] , [data-repub] .vpb, [data-repub] .vpb-note, [data-repub] .vpb-pin, [data-repub] .vpb-actions { animation: none !important; } }
`;

const Styles = () => <style href="concorde-publication-badge" precedence="default">{PUBLICATION_BADGE_CSS}</style>;

export function PublicationBadge({ status, label }: { status: PublicationStatus; label?: string }): JSX.Element {
  const text = label ?? PUBLICATION_LABEL[status];
  return <><Styles /><span className={`vpb vpb--${status}`} role="status" aria-label={text}><span>{text}</span></span></>;
}

/** Chincheta de una publicación fijada arriba de la lista (las desiertas). Va antes del nombre. */
export function PublicationPin(): JSX.Element {
  return <><Styles /><svg className="vpb-pin" viewBox="0 0 24 24" role="img" aria-label="Fijada"><title>Fijada</title><path d="M16 9V4h1a1 1 0 0 0 0-2H7a1 1 0 0 0 0 2h1v5a3 3 0 0 1-3 3v2h6v7l1 1 1-1v-7h6v-2a3 3 0 0 1-3-3z" fill="currentColor" /></svg></>;
}

export default PublicationBadge;
